fixtures.source:
// Deliberately malformed: missing ';' after the first assignment.
// The parser must reject this with a structured file:line:col error rather
// than crash or silently misparse.
fun main() {
  x = 5
  __voblint_check(0 < x);
}

// Syntactically valid (min(x) parses like any ordinary call), but wrong
// arity for the special call it resolves to: min needs exactly two
// arguments. classify_special SD_Min [x] = None, so wf_source_com rejects
// it -- not a silent fallback to treating min as an ordinary, undeclared
// procedure. Rejected here by the CLI's well-formedness gate rather than
// reaching the analyzer at all.
fun main() {
  x = 3;
  z = min(x);
  __voblint_check(0 < z);
}

// Ported from Example_Compile_Regression.thy (unknown_call_rejected): a call names no procedure of the program.
// The well-formedness gate rejects the program before any analysis runs.
fun main() {
  q();
}

// Ported from Example_Compile_Regression.thy (wrong_call_arity_rejected): a call passes more arguments than the callee has formals.
// The well-formedness gate rejects the program before any analysis runs.
fun f(a) {
  a = a + 1;
}
fun main() {
  f(1, 2);
}

// Ported from Example_Compile_Regression.thy (duplicate_formals_rejected): two formals share a name.
// The well-formedness gate rejects the program before any analysis runs.
fun f(a, a) {
  a = 1;
}
fun main() {
  f(1, 2);
}

// Ported from Example_Compile_Regression.thy (global_formal_rejected): a formal shadows a declared global.
// The well-formedness gate rejects the program before any analysis runs.
global g;
fun f(g) {
  g = 1;
}
fun main() {
  f(1);
}

// Ported from Example_Compile_Regression.thy (root_return_rejected): main must not return, since a top-level Return never completes.
// The well-formedness gate rejects the program before any analysis runs.
fun main() {
  x = 1;
  return;
}

// Ported from Example_Compile_Regression.thy (value_call_requires_value_provider): a value call to a procedure that returns nothing.
// The well-formedness gate rejects the program before any analysis runs.
fun p() {
  x = 1;
}
fun main() {
  y = p();
}

// Ported from Example_Compile_Regression.thy (duplicate_procedure_names_rejected): two procedures share a name.
// The well-formedness gate rejects the program before any analysis runs.
fun f() {
  x = 1;
}
fun f() {
  x = 2;
}
fun main() {
  f();
}

// Straight-line arithmetic, one exact write, one check.
// See 07-sign-precision/precision/01-straight_line_sign.vimp for the same
// program under Sign, also PROVED since the #99 fix.
fun main() {
  x = 5;
  __voblint_check(0 < x); // PROVED
}

// Mirror of 01-straight_line_proved.vimp's PROVED witness: an exact
// negative write refutes the same condition instead of proving it. Pairs
// PROVED and REFUTED witnesses for one mechanism (exact assignment),
// rather than leaving REFUTED coverage to a single case buried inside a
// mixed-verdict file.
fun main() {
  x = 0 - 5;
  __voblint_check(0 < x); // REFUTED
}

// Unconstrained value from __voblint_nondet_int(): nothing bounds x before the check.
fun main() {
  x = __voblint_nondet_int();
  __voblint_check(0 < x); // UNKNOWN
}

// Adapted from Goblint tests/regression/01-cpa/28-interval.c (x != 0 in the
// true arm of if (x)) and 36-apron/18-branch2.c. Inside if (x) and if (!!x)
// every execution has x != 0, so the concrete result is
// fixed. Goblint proves it through DefExc's exclusion set {0}. No component of
// the reduced product Sign x Interval x Parity x Congruence can represent
// "everything except 0": the sign lattice has no NonZero element (its
// non-trivial elements are Neg, NonPos, Zero, NonNeg, Pos), an interval is
// convex, parity and congruence cannot carve a single point out of Top. The
// guard refines x to Top in every component and (x != 0) stays UNKNOWN.
// interval and sign alone answer the same.
fun main() {
  x = __voblint_nondet_int();
  if (x) {
    __voblint_check(x != 0); // UNKNOWN
  }
  if (!!x) {
    __voblint_check(x != 0); // UNKNOWN
  }
}

// Adapted from Goblint tests/regression/01-cpa/28-interval.c (a != b is
// UNKNOWN there too). Every execution leaves (a, b) at (8, 9) or (9, 8), so
// a != b concretely holds. The join after the branch is pointwise: a and b
// each become [8,9] and the state no longer records that a = 8 pairs with
// b = 9. An interval domain has no way to relate two variables, so
// (a != b) over [8,9] x [8,9] is UNKNOWN. int agrees.
fun main() {
  z = __voblint_nondet_int();
  if (z != 0) {
    a = 8;
    b = 9;
  } else {
    a = 9;
    b = 8;
  }
  __voblint_check(a != b); // UNKNOWN
}

// On the true arm of x + 1 < 5, every execution has x <= 3, so x < 4 holds.
// Interval's inverse of < refines x + 1 to [-inf,4], but its inverse of + is
// the identity, so nothing reaches x and the check stays unknown. An
// interval analysis that inverts addition, x := x meet (r - 1), would prove
// it (Nipkow and Klein, Concrete Semantics, Sect. 13.8.3).
fun main() {
  x = __voblint_nondet_int();
  if (x + 1 < 5) {
    __voblint_check(x < 4); // UNKNOWN
  }
}

// Inside the guard x is 1 or 2, so x == 1 || x == 2 holds in every store.
// check_query (Abstract_Checks.thy) judges both disjuncts in the same state
// x=[1,2]: eq([1,2],[1,1]) and eq([1,2],[2,2]) are both unknown, and so is
// their disjunction. The disjunction is never re-judged under the refinement
// of its first operand. Goblint's CIL front end lowers || into branches, so
// there the second operand is judged after the first has failed.
// The nested form below does not help Voblint either: inv_eq_ivl
// (Interval_Backward.thy) leaves both intervals unchanged on a definite
// inequality, so the else branch of x == 1 keeps x=[1,2] instead of [2,2].
fun main() {
  x = __voblint_nondet_int();
  if (x >= 1 && x <= 2) {
    __voblint_check(x == 1 || x == 2); // UNKNOWN
    if (x == 1) {
      t = 1;
    } else {
      __voblint_check(x == 2); // UNKNOWN
    }
  }
}

// Both guards state 0 < i < j < 10, so i <= 8 and j >= 2 hold in both arms.
// bfilter (Backward_Domain.thy) refines a conjunction from right to left
// (bfilter (And b1 b2) True d = bfilter b1 True (bfilter b2 True d)), each
// conjunct once, without iterating to a local fixpoint. Which bound reaches
// which variable therefore depends on the order of the conjuncts: in the
// first arm i=[1,8] but j=[-inf,9], in the second j=[2,9] but i=[1,+inf].
// Repeating the pass would give i=[1,8] and j=[2,9] in both.
fun main() {
  i = __voblint_nondet_int();
  j = __voblint_nondet_int();
  if (0 < i && i < j && j < 10) {
    __voblint_check(i <= 8); // PROVED
    __voblint_check(j >= 2); // UNKNOWN
  }
  if (j < 10 && i < j && 0 < i) {
    __voblint_check(i <= 8); // UNKNOWN
    __voblint_check(j >= 2); // PROVED
  }
}

// Branch and join: y is 1 or 2 depending on the arm taken, so the check
// holds on every path regardless of which arm the analysis takes.
fun main() {
  x = 0;
  if (x < 1) {
    y = 1;
  } else {
    y = 2;
  }
  __voblint_check(0 < y); // PROVED
}

// Counted loop: exercises widening/narrowing on a bounded induction variable.
fun main() {
  x = 0;
  while (x < 10) {
    x = x + 1;
  }
  __voblint_check(0 < x); // PROVED
}

// __voblint_nondet_int() gives x no bound at all (Top), but the guard on each branch
// narrows it before the check runs: the true arm's assume tightens x to
// [1,+inf), the false arm's to (-inf,0]. Both checks read back their own
// arm's narrowed range, not the pre-branch Top -- a guard/assume-narrowing
// regression, not a join regression (unlike 01-if_else.vimp, the check is
// inside each arm, before any post-if join). The false arm's (x <= 0) is a
// permanent regression witness for interval_less_false's boundary fix
// (Interval_Numeric_Queries.thy): it used to report UNKNOWN here because
// interval_less_false required a STRICT upper<lower separation (u2 < l1)
// to refute "0<x", missing the touching-boundary case x=[-inf,0] where
// u2=l1=0 -- sound but needlessly conservative, now u2<=l1.
fun main() {
  x = __voblint_nondet_int();
  if (0 < x) {
    __voblint_check(0 < x); // PROVED
  } else {
    __voblint_check(x <= 0); // PROVED
  }
}

// "0 < y" holds on the then-branch: x is 5, so the second disjunct
// "(x < 0) == 1" is false in every state, and the branch is taken only when the
// first disjunct is true.
//
// Refining a disjunction joins both sides, so the analyzer sees it only because
// each side is gated first: bfilter's "Or _ _ True" case narrows each disjunct
// with the same feasibility test the branch transfer applies to a whole
// condition, and an infeasible side then contributes bot -- the unit of the
// join -- instead of its own unrefined incoming state. Without that gate the
// second disjunct would contribute y unconstrained and the join would discard
// what the first disjunct established. The branch transfer's own gate cannot
// substitute for it: it reads the whole condition, whose abstract value is
// [0,1], and so decides nothing.
//
// The else-branch assumes neither disjunct, which bfilter's "Or _ _ False" case
// narrows sequentially rather than by a join -- a different path through the
// same operator, and one the gate plays no part in.
//
// The conjunctive half of the gate is 05-infeasible_conjunct_dropped.vimp.
fun main() {
  x = 5;
  y = __voblint_nondet_int();
  if (0 < y || (x < 0) == 1) {
    __voblint_check(0 < y); // PROVED
  } else {
    __voblint_check(y < 1); // PROVED
  }
}

// The conjunctive half of the branch gate, dual to
// 04-infeasible_disjunct_dropped.vimp. Concretely "y < 1" holds on the
// else-branch: x is 5, so "(x < 0) == 0" is true in every state, and the branch
// is taken only when the second conjunct is false.
//
// bfilter's "And _ _ False" case joins the two sides -- assuming the negation of
// a conjunction rules out one conjunct or the other -- and gates each side
// first. The first conjunct is infeasible for the assumed polarity, since it is
// definitely true, so that side contributes bot instead of its own unrefined
// incoming state and the join keeps what the second side established. Without
// the gate the first side would contribute y unconstrained: Interval's
// "inv_eq False" is the sound identity, so the Eq inversion narrows nothing,
// and the join would discard "y <= 0".
//
// The then-branch is the sequential "And _ _ True" case, where both conjuncts
// are narrowed in turn and no join is involved.
fun main() {
  x = 5;
  y = __voblint_nondet_int();
  if ((x < 0) == 0 && 0 < y) {
    __voblint_check(0 < y); // PROVED
  } else {
    __voblint_check(y < 1); // PROVED
  }
}

// Adapted from Goblint tests/regression/01-cpa/28-interval.c, the interval
// sanity battery, without its UNKNOWN checks: the true arm of if (x) and the
// a/b correlation live in known-imprecision/01-no_exclusion_set.vimp and
// known-imprecision/02-nonrelational_join.vimp, the nondet-decided a == 8 and
// b == 8 in soundness/01-truthiness_guard_underdetermined.vimp. What stays:
// truthiness guards (if (!x), !!t, !f, dead arms of if (a) and if (!a)),
// constants joined into [8,9] and every <, <=, >, >= threshold on them,
// comparisons as int values, a counted loop with x == 10
// after it, and the tail after Goblint's early return restructured as nesting
// because main may not return.
// int gives the same verdicts.
fun main() {
  a = 1;
  b = 2;
  x = __voblint_nondet_int();
  z = __voblint_nondet_int();
  w = __voblint_nondet_int();
  f = 0;
  t = 42;
  if (!x) {
    __voblint_check(x == 0); // PROVED
  }
  __voblint_check(!!t); // PROVED
  __voblint_check(!f); // PROVED
  if (a) {
    a = a;
  } else {
    __voblint_check(false); // NOWARN (unreachable)
  }
  if (!a) {
    __voblint_check(false); // NOWARN (unreachable)
  } else {
    a = a;
  }
  if (z != 0) {
    a = 8;
    b = 9;
  } else {
    a = 9;
    b = 8;
  }
  __voblint_check(a); // PROVED
  __voblint_check(a < 10); // PROVED
  __voblint_check(a <= 9); // PROVED
  __voblint_check(a >= 8); // PROVED
  __voblint_check(7 < b); // PROVED
  __voblint_check(b >= 8); // PROVED
  __voblint_check((a < 10) == 1); // PROVED
  __voblint_check((9 < a) == 0); // PROVED
  __voblint_check(((a == b) >= 0)); // PROVED
  __voblint_check(((a == b) <= 1)); // PROVED
  x = 0;
  while (x < 10) {
    __voblint_check(x >= 0); // PROVED
    __voblint_check(x <= 9); // PROVED
    x = x + 1;
  }
  __voblint_check(x == 10); // PROVED
  if (w >= 0) {
    if (0 < w) {
      __voblint_check(true); // PROVED
    }
  }
}

// Adapted from Goblint tests/regression/36-apron/18-branch2.c and
// 27-inv_invariants/03-ints-not.c. A bare int as a condition means != 0, so
// the true arms of if (!i) and if (!x) both refine the
// nondeterministic value to exactly [0,0]: i == 0 and x == 0 are PROVED and
// i < 0 is REFUTED (Goblint: bare, bare, FAIL). The other arms only learn
// "not 0", which decides nothing about i >= 1 or x == 1; those UNKNOWNs are
// in soundness/01-truthiness_guard_underdetermined.vimp. sign and int agree.
fun main() {
  i = __voblint_nondet_int();
  x = __voblint_nondet_int();
  if (!i) {
    __voblint_check(i == 0); // PROVED
    __voblint_check(i < 0); // REFUTED
  }
  if (!x) {
    __voblint_check(x == 0); // PROVED
  }
}

// x == 0 && x == 1 is self-contradictory (no integer is both), and so is
// y == 0 && y == 1; either disjunct's own two-step backward narrowing
// intersects x's (or y's) interval down to Bottom. bfilter_lifted
// (Backward_Domain.thy) canonicalizes each arm to structural Bottom before
// joining, so the pointwise And/Or join no longer lets the other disjunct's
// untouched x (or y) location survive and override the narrowed-Bottom arm:
// the whole guard comes back witness-bottom, and the branch is recognized
// as unreachable.
fun main() {
  x = __voblint_nondet_int();
  y = __voblint_nondet_int();
  if ((x == 0 && x == 1) || (y == 0 && y == 1)) {
    __voblint_check(x == 5); // NOWARN (unreachable)
  }
}

// A false branch leaves x unchanged and reaches the following statement.
// A true branch executes its body and reaches the same continuation.
fun main() {
  x = 4;
  if (x < 0) {
    x = 9;
  }
  __voblint_check(x == 4); // PROVED
  if (0 < x) {
    x = 5;
  }
  __voblint_check(x == 5); // PROVED
}

// Exactly one arm executes; a chain may omit or include its final else.
fun choose(x) {
  if (x < 0) {
    return -1;
  } else if (x == 0) {
    return 0;
  } else {
    return 1;
  }
}

fun main() {
  x = 0;
  y = 9;
  if (x < 0) {
    y = -1;
  } else if (x == 0) {
    y = 0;
  } else if (x < 10) {
    y = 1;
  }
  __voblint_check(y == 0); // PROVED
  z = choose(x);
  __voblint_check(z == 0); // PROVED
}

// x = 0; while (x < 20) x = x + 1. The loop head settles at x = [0,20]
// without widening loss: the guard x < 20 narrows the body entry to [0,19],
// the increment gives [1,20], and its join with the initial [0,0] is the
// head value again. The exit is [20,20]. The EXPECT-GRAPH block pins the
// head, body and exit values and the compiled CFG layout (pp1 loop head,
// pp2 body entry, pp3 exit).
//
// Ported from Exec_Interval_Run.thy (loop_head_ivl, loop_body_ivl,
// loop_head_ivl_td, loop_body_ivl_td, loop_head_warrow),
// Example_Interval_Loop_Coverage.thy (loop_cfg_full, loop_body_x_from_assume)
// and Example_Guard_Refinement.thy (refine_x_lt_20, body_step_refined,
// loop_join_refined). The join rule's run of this program is
// Example_Interval_DG_Flagship.thy; the other update rules agree on the same
// loop shape in 06-reachability/precision/10, 15, 16, 17.


fun main() {
  x = 0;
  while (x < 20) {
    x = x + 1;
  }
  __voblint_check(x == 20); // PROVED
}

// Backward guard refinement of x = [0,20] against the threshold 10, for each
// direct comparison and both branch polarities, plus x < 20 and a guard no
// state in y = [5,9] satisfies, whose arm is dead. x != 10 leaves x = [0,20]
// on its true arm (an interval cannot exclude an interior point, see
// known-imprecision/01-no_exclusion_set.vimp) and narrows it to [10,10] on
// its false arm.
//
// Ported from Example_Guard_Refinement.thy: refine_direct_comparisons_true,
// refine_direct_comparisons_false, refine_x_lt_20,
// guard_infeasible_canonical_bot.
fun main() {
  x = __voblint_nondet_int();
  y = __voblint_nondet_int();
  if (0 <= x && x <= 20 && 5 <= y && y <= 9) {
    if (x <= 10) {
      __voblint_check(x >= 0); // PROVED
      __voblint_check(x <= 10); // PROVED
    } else {
      __voblint_check(x >= 11); // PROVED
      __voblint_check(x <= 20); // PROVED
    }
    if (x > 10) {
      __voblint_check(x >= 11); // PROVED
      __voblint_check(x <= 20); // PROVED
    } else {
      __voblint_check(x >= 0); // PROVED
      __voblint_check(x <= 10); // PROVED
    }
    if (x >= 10) {
      __voblint_check(x >= 10); // PROVED
      __voblint_check(x <= 20); // PROVED
    } else {
      __voblint_check(x >= 0); // PROVED
      __voblint_check(x <= 9); // PROVED
    }
    if (x != 10) {
      __voblint_check(x >= 0); // PROVED
      __voblint_check(x <= 20); // PROVED
    } else {
      __voblint_check(x == 10); // PROVED
    }
    if (x < 20) {
      __voblint_check(x >= 0); // PROVED
      __voblint_check(x <= 19); // PROVED
    }
    if (y < 0) {
      __voblint_check(false); // NOWARN (unreachable)
    }
  }
}

// Adapted from Goblint tests/regression/36-apron/18-branch2.c (i >= 1 is
// UNKNOWN!), 27-inv_invariants/03-ints-not.c (x == 1 is UNKNOWN!) and
// 01-cpa/28-interval.c (a == 8, b == 8 are UNKNOWN). Each value is an
// unconstrained __voblint_nondet_int(): inside if (i) the guard only rules out
// 0, so i = 1 and i = -1 are both executions; likewise x inside if (!!x).
// a and b are 8 or 9 depending on the nondet z. Every check has a
// satisfying and a violating run, so UNKNOWN is the only sound verdict --
// refining if (i) to [1,+inf] would be a soundness bug, and this fixture is
// the witness against it.
fun main() {
  i = __voblint_nondet_int();
  x = __voblint_nondet_int();
  z = __voblint_nondet_int();
  if (i) {
    __voblint_check(i >= 1); // UNKNOWN
  }
  if (!!x) {
    __voblint_check(x == 1); // UNKNOWN
  }
  if (z != 0) {
    a = 8;
    b = 9;
  } else {
    a = 9;
    b = 8;
  }
  __voblint_check(a == 8); // UNKNOWN
  __voblint_check(b == 8); // UNKNOWN
}

// Procedure layout regression: the procedure list is known before any body is compiled, so a call may
// target the current procedure (f's direct self-recursion), a sibling
// declared later (g calling h, a forward reference needing no second
// pass), or a mutually recursive pair (g and h calling each other). The
// claim here is purely structural -- which callee each call edge targets,
// and where each procedure's block starts and ends -- not a value the
// analysis proves. G defaults to 0 and neither branch of f's body changes
// it, so f's own condition G<1 holds at every recursive re-entry: f
// provably never reaches its else branch, never returns to main, and the
// trailing check after inc() is therefore proved dead (NOWARN) -- a true
// consequence of the source. The
// graph below marks that check [dead] at pp13, agreeing with the DEAD the
// text report prints for it: both readings come from the same solved
// table, so a check the analysis proves unreachable cannot read as decided
// in one and dead in the other. The
// graph snapshot below pins which callee each call edge targets and each
// procedure's block layout; the call and
// combine edges after f's call site still appear in it; only their
// solved state is dead.

global G;
fun f() {
  if (G < 1) { f(); } else { G = G; }
}
fun g() { h(); }
fun h() { g(); }
fun inc() { G = G + 1; }
fun main() { f(); g(); inc(); __voblint_check(true); } // NOWARN

// Two call sites to the same procedure share ONE activation context
// (--graph-snapshot shows both "enter square(...)" edges landing on the
// same cluster_ctx_1): square's entry is one CFG node, revisited once per
// call site, not resolved per call site. This is call-site (in)sensitivity
// -- a context-sensitivity gap distinct from (and not fixed by) the
// Base-style D/G migration that resolved 04-globals/precision/
// 02-global_var.vimp's flow-insensitive global summary: even with the
// whole abstract state lifted into the local unknown, the entry node
// itself is still keyed on the unit context, so the D/G solver evaluates
// it once against both incoming edges. Under the warrowing update rule
// this repeated evaluation widens the entered parameter's bound on the
// second visit, so neither call's own exact argument (9 or 16) survives
// -- both checks come back UNKNOWN, not a narrower sound join. A
// call-string- or entry-state-context-sensitive analysis keys the entry per
// call site or per entered value instead (see
// precision/04-two_call_sites_entry_state.vimp).
fun square(n) {
  return n * n;
}
fun main() {
  a = square(3);
  b = square(4);
  __voblint_check(a == 9); // UNKNOWN
  __voblint_check(b == 16); // UNKNOWN
}

// x == 6 and y == 20 hold concretely, but without a context both calls share
// twice's single FunctionEntry unknown. Its seed receives p = 3 from one site
// and p = 10 from the other; the join rule joins them to [3,10] without
// widening, so the one analyzed body returns [6,20] to both callers. The
// bounds survive (contrast the warrow default in
// 19-paper-examples/known-imprecision/04-context_insensitive_calls.vimp,
// which widens to [6,+inf]); the per-call values do not.
//
// Ported from Example_Interval_DG_IP_Flagship.thy: twice_p_at_entry,
// twice_ret_at_exit, twice_x_computed, twice_y_computed.
fun twice(p) {
  __voblint_check(p >= 3); // PROVED
  __voblint_check(p <= 10); // PROVED
  return p + p;
}
fun main() {
  x = twice(3);
  y = twice(10);
  __voblint_check(x >= 6); // PROVED
  __voblint_check(x <= 20); // PROVED
  __voblint_check(y >= 6); // PROVED
  __voblint_check(y <= 20); // PROVED
  __voblint_check(x == 6); // UNKNOWN
  __voblint_check(y == 20); // UNKNOWN
}

// Procedure call with a formal and a used return value.
fun inc(n) {
  return n + 1;
}
fun main() {
  r = inc(5);
  __voblint_check(0 < r); // PROVED
}

// A call with no relation to x (not passed as an actual, no shared global)
// must leave the caller's own binding of x untouched across the call --
// the D/G combine step at the call-to-return edge restores the caller's
// locals rather than merging in anything from the callee's activation.
fun noop() {
  return 0;
}
fun main() {
  x = 5;
  noop();
  __voblint_check(x == 5); // PROVED
}

// bump's local x (its formal's shadow) and main's local x are distinct
// activation-local bindings that happen to share a name. If combine ever
// let a callee's local leak back into the caller's own binding of the same
// name, main's x would come back as 105 instead of surviving at 1 -- this
// is the same activation-local boundary #99's D/G combine fix protects,
// exercised through a name COLLISION rather than an unrelated call.
fun bump(x) {
  x = x + 100;
  return x;
}
fun main() {
  x = 1;
  r = bump(5);
  __voblint_check(x == 1); // PROVED
  __voblint_check(r == 105); // PROVED
}

// Same program as known-imprecision/01-two_call_sites_same_procedure.vimp,
// under entry-state context sensitivity instead of the default flat
// analysis. There, both calls to square share ONE activation, whose entry
// is widened across the two call sites (n = [3,+inf]), so a and b read
// back [-inf,+inf] and neither can be proved. Here, each call is keyed by its own entered
// argument value ([9,9] vs [16,16] respectively), so square is analyzed
// once per distinct entry-state context instead of joined into one shared
// summary -- an observable precision benefit of #108's context analysis
// over the flat default, not a different claim about the concrete program
// (both checks are true for the same reason in both files: 3*3=9,
// 4*4=16).
fun square(n) {
  return n * n;
}
fun main() {
  a = square(3);
  b = square(4);
  __voblint_check(a == 9); // PROVED
  __voblint_check(b == 16); // PROVED
}

// Minimal reproducer from issue #113: n=5 makes "n < 2" false, so the
// "return 1" branch is provably unreachable. Before the reachability-lift
// fix, the dead branch's own #ret := 1 assignment transfer still produced
// a non-bottom #ret=[1,1] from an already-unreachable predecessor state,
// and the exit node's join widened the result to a=[1,500] instead of the
// exact a=[500,500]. Locks in the fixed, precise result -- flat, no
// procedure recursion, no --context flag. The recursive-factorial variant of
// this same pattern is 06-recursive_factorial_dead_branch_no_bottom_leak.vimp,
// which proves its results exactly under entry-state context sensitivity.
fun f(n) {
  if (n < 2) {
    return 1;
  } else {
    return n * 100;
  }
}

fun main() {
  a = f(5);
  __voblint_check(a == 500); // PROVED
}

// Recursive factorial under entry-state context sensitivity. Solver-key
// inspection (not just this CLI report) confirms context separation itself
// is exact: factorial's entry is covered by four distinct, precise
// contexts (n=[1,1], [2,2], [3,3], [4,4]), each with an exact n.
//
// At each n>=2 context, the "return 1" base-case edge (guarded by n<2) is
// structurally unreachable there: the reachability-lift fix (#113) makes
// that branch's own local state genuinely Bot in the lifted D/G carrier,
// not merely imprecise, so its #ret := 1 assignment never contributes a
// spurious [1,1] to FunctionResult's join. Reaching this result at all
// additionally required buffering same-origin, same-key Side contributions
// in the keyed D/G generator before publication (#123): without it, two
// predecessor edges (or a callee-return combine and an intra edge) writing
// the same global key within one equation evaluation destabilized the
// update rule's per-origin gate and never converged. See
// 03-procedures/precision/05-dead_branch_no_bottom_leak.vimp for the flat,
// non-recursive, non-context minimal case of the same dead-branch pattern.
fun factorial(n) {
  __voblint_check(0 < n); // PROVED

  if (n < 2) {
    return 1;
  } else {
    r = factorial(n - 1);
    __voblint_check(0 < r); // PROVED
    return n * r;
  }
}

fun main() {
  a = factorial(3);
  b = factorial(4);

  __voblint_check(a == 6);   // PROVED
  __voblint_check(b == 24);   // PROVED
}

// Same program as 04-two_call_sites_entry_state.vimp, explicit --globals
// join instead of entry-state's implicit Warrow default. The routed
// entry-state equation system names no solve function of its own -- only
// the shared D/G spec and the routing policy -- so it is exactly as
// solver-independent as the flat Ctx_None equation system already is, and
// this program crosses no loop under either context, so join needs no
// widening to terminate and reproduces the exact per-context result.
fun square(n) {
  return n * n;
}
fun main() {
  a = square(3);
  b = square(4);
  __voblint_check(a == 9); // PROVED
  __voblint_check(b == 16); // PROVED
}

// Same program as 04-two_call_sites_entry_state.vimp, explicit --globals
// per-origin instead of entry-state's implicit Warrow default -- see
// 07-two_call_sites_entry_state_join_solver.vimp for why the routed
// equation system underneath accepts any solver the same way the flat one
// does.
fun square(n) {
  return n * n;
}
fun main() {
  a = square(3);
  b = square(4);
  __voblint_check(a == 9); // PROVED
  __voblint_check(b == 16); // PROVED
}

// Both branches of the if end in a call to the same procedure, so both calls
// resume at the same CFG node: the compiler emits pp4 --call-to-return f--> pp6
// and pp5 --call-to-return f--> pp6. That node's equation therefore carries two
// call actions to f, both routing to the same context, so one right-hand-side
// evaluation performs two side effects to the same callee-entry seed key.
//
// Two side effects to one key from one right-hand-side evaluation used to
// livelock: the per-origin update was applied eagerly per side effect against
// the running accumulate, so the dead branch's write landed first carrying
// bottom, dropped the seed below what the live branch had established, and the
// two writes destabilized the callee alternately in a fixed 10-step cycle. The
// contract that settles it -- one right-hand-side evaluation contributes one
// aggregated value per target key -- is stated in the sibling case 10.
//
// Reversing the branch polarity hides the ordering entirely, so this case pins
// the polarity that exercised it, under --context none, where the default
// Interval configuration reaches this shape.
fun f(n) {
  return n;
}
fun main() {
  x = 5;
  if (x < 2) {
    a = f(1);
  } else {
    a = f(1);
  }
  __voblint_check(x == 5); // PROVED
}

// The sibling of 09 with no dead branch: an unconstrained condition leaves both
// call sites reachable, and they enter f with different values, so the two side
// effects to the shared callee-entry seed key carry two genuinely different
// states rather than bottom and a state.
//
// This is why guarding the callee-entry side effect on a bottom entered state
// -- Goblint's `if not (S.D.is_bot v) then sidel (FunctionEntry f, fc) v` --
// does not by itself settle the shared-resume-node case: whichever of the two
// live writes the solver evaluates first is still a partial accumulate, and the
// per-origin slot still dips when it lands. The contract that does settle it is
// that one right-hand-side evaluation contributes one aggregated value per
// target key.
//
// x is unconstrained, so nothing here claims a value for a -- the check is on
// the caller's own local, which the call cannot touch.
fun f(n) {
  return n;
}
fun main() {
  x = __voblint_nondet_int();
  y = 7;
  if (x < 2) {
    a = f(1);
  } else {
    a = f(2);
  }
  __voblint_check(y == 7); // PROVED
}

// 09's program under an explicit --globals per-origin. The shared resume node
// makes one right-hand-side evaluation write the callee-entry seed key twice,
// and per-origin is the update rule that shape is sharpest against: it keeps
// one slot per write origin and overwrites that slot, so a partial accumulate
// replaces a completed one from the same origin rather than joining into it.
//
// 09 pins the default rule; this pins the update rule the mechanism actually
// names, so a regression in the aggregation cannot hide behind whichever rule
// the default happens to select.
fun f(n) {
  return n;
}
fun main() {
  x = 5;
  if (x < 2) {
    a = f(1);
  } else {
    a = f(1);
  }
  __voblint_check(x == 5); // PROVED
}

// 09's program under --globals join, which folds every contribution into one
// slot and therefore never dips: this case terminates with or without the
// per-key aggregation. It is here as the control. Aggregating writes changes
// when a key is published within one right-hand side, so it changes the order
// the solver visits unknowns in, and narrowing is order-sensitive -- a mode
// that was already healthy is exactly where an ordering-induced precision
// regression would show up unexplained.
fun f(n) {
  return n;
}
fun main() {
  x = 5;
  if (x < 2) {
    a = f(1);
  } else {
    a = f(1);
  }
  __voblint_check(x == 5); // PROVED
}

// Two call sites sharing one resume node, but to different procedures, so the
// node's two call actions carry two distinct seed keys rather than one key
// twice. Aggregation must keep them apart: a per-key accumulator that collapsed
// distinct keys would publish f's entered state into g's seed and vice versa,
// which is unsound rather than merely imprecise.
//
// The complement of 09: 09 pins that two writes to one key become one write,
// this pins that two writes to two keys stay two writes.
fun f(n) {
  return n;
}
fun g(n) {
  return n + 1;
}
fun main() {
  x = 5;
  if (x < 2) {
    a = f(1);
  } else {
    a = g(1);
  }
  __voblint_check(x == 5); // PROVED
}

// 09's program under entry-state context sensitivity. Both call sites enter f
// with the same argument, so formals_context derives the same context for both
// and the two routed seeds land on the same key -- the collision survives
// context sensitivity precisely when the two calls agree on the entered
// formals, which is the case a per-call-site keying would otherwise be assumed
// to separate.
fun f(n) {
  return n;
}
fun main() {
  x = 5;
  if (x < 2) {
    a = f(1);
  } else {
    a = f(1);
  }
  __voblint_check(x == 5); // PROVED
}

// The shared resume node inside a loop, so the seed key is written twice per
// right-hand-side evaluation and that evaluation is itself revisited under
// widening and narrowing. Aggregating the two writes moves the key's
// publication to after every contribution has been read, which reorders the
// unknowns the solver visits on the first pass; narrowing is sensitive to that
// order, so a loop is where a reordering that costs precision would surface.
fun f(n) {
  return n;
}
fun main() {
  i = 0;
  while (i < 10) {
    if (i < 5) {
      a = f(1);
    } else {
      a = f(1);
    }
    i = i + 1;
  }
  __voblint_check(0 < i); // PROVED
}

// Acceptance case for #108's entry-state context analysis: an unconstrained
// argument (__voblint_nondet_int()) must collapse to ONE wide entry-state context at p's
// call site -- the entered value's own abstract state, not a context keyed
// per concrete value -- so the analysis terminates instead of diverging
// over every value __voblint_nondet_int() could produce. The checked condition inside p
// is itself unconstrained by that wide context, so UNKNOWN is the only
// sound verdict here; the acceptance claim is that entry-state context
// sensitivity runs and reports soundly for an unbounded argument, not that
// it proves anything about this particular check (see
// precision/04-two_call_sites_entry_state.vimp for the precision benefit
// entry-state context sensitivity actually buys on a bounded argument).
fun p(a) {
  __voblint_check(0 < a); // UNKNOWN
}
fun main() {
  x = __voblint_nondet_int();
  p(x);
}

// The concrete value of total here is fixed at 7, so total < 100 genuinely
// holds -- but the analysis cannot establish it. Mechanism: the loss is on
// total, not on the entered formal. inc's body writes total := total + n,
// so total's own value re-enters its next contribution and the chain
// 0, [0,3], [0,7], ... ascends without bound; Apinis warrowing must cut the
// upper bound to +inf to terminate. The following narrowing phase recovers
// the lower bound (total is [3,+inf], not [-inf,+inf]) but not the upper
// one, so a bound like < 100 stays undecided. n itself is exact at [3,4].
//
// The chain has a single write origin, so the per-origin update rules do
// not recover it either: they separate contributions from distinct origins
// before widening, and there is only one origin here to separate.
//
// 04-globals/precision/02-global_var.vimp is the same program's decidable
// half (0 < total, PROVED from the recovered lower bound); only the check
// that the widening actually costs lives here.

global total;
fun inc(n) {
  total = total + n;
}
fun main() {
  total = 0;
  inc(3);
  inc(4);
  __voblint_check(total < 100); // UNKNOWN
}

// counter is called twice from the same call site, so its concrete value
// at the check is fixed at 2 -- yet the analysis cannot bound it above.
// Mechanism: a declared global's write inside a called procedure feeds the
// shared unknown's own equation (the assignment reads the same slot it
// writes), so the two contributions ascend ([0,0], then a self-referencing
// [0,1], [0,2], ...) and warrowing must widen the upper bound to +inf to
// terminate -- the same call-site widening as
// 04-globals/known-imprecision/01-repeated_call_site_widening.vimp. A
// single call to p, by contrast, needs no fixpoint iteration and resolves
// counter exactly; it is the repetition, not the declaration itself, that
// costs precision here. Contrast with
// 04-globals/precision/05-glocal_not_global_by_name.vimp: same program,
// same two calls, but Glocal is undeclared and stays exact throughout.
global counter;
fun p() {
  counter = counter + 1;
}
fun main() {
  Glocal = 1;
  p();
  p();
  __voblint_check(counter < 5); // UNKNOWN
}

// The sequence of 06-sequential_global_proved.vimp with program globals
// flow-insensitive. x lives at its own global unknown, which must cover every
// value x holds anywhere: the initial zero, published by the program entry,
// joins the two writes, and the check at the end sees x in [0,1]. The exact
// check is lost; the range check survives.
global x;
fun main() {
  x = 0;
  x = 1;
  __voblint_check(x == 1); // UNKNOWN
  __voblint_check(0 <= x); // PROVED
}

// A declared global's value before any write is its documented
// Goblint-style zero-initialized default (cinit_sign_st), read back
// exactly -- see also 02-global_var.vimp (Interval), which locks in a
// declared global's value after it is actually written.
global g;
fun main() {
  __voblint_check(g == 0); // PROVED
}

// Declared global mutated across two calls; exercises declared_global_vars
// wiring. Base-style migration acceptance case (issue tracked alongside
// 12-widening/precision/01-global_self_feedback.vimp): total lives in the
// same reachability-lifted local unknown as every local, flow-sensitively
// through both calls to inc, so its exact value (7) survives to the check
// -- no separate flow-insensitive global summary exists to join total's
// prior value against its own write anymore.
global total;
fun inc(n) {
  total = total + n;
}
fun main() {
  total = 0;
  inc(3);
  inc(4);
  __voblint_check(0 < total); // PROVED
}

// Call/return semantics of the entry-state context analysis over a declared
// global. The local unknown carries every VIMP variable, so g crosses the
// call boundary in the same slot a local does: bump reads the g main wrote
// before the call, writes it, and returns it, and main then observes both
// the returned value and the callee's update. The three calls carry
// different arguments -- two literals and one that is itself the global g
// -- so bump is analyzed under three distinct entry-state contexts
// ([5,5], [4,4], [19,19]) and n binds exactly in each. The third call also
// locks in that a global-valued actual argument is evaluated against the
// caller's real state at the call site, not a globals-bottomed one.
global g;
fun bump(n) {
  g = g + n;
  return g;
}
fun main() {
  g = 10;
  a = bump(5);
  b = bump(4);
  __voblint_check(a == 15); // PROVED
  __voblint_check(b == 19); // PROVED
  __voblint_check(g == 19); // PROVED
  c = bump(g);
  __voblint_check(c == 38); // PROVED
  __voblint_check(g == 38); // PROVED
}

// A declared global written with a constant, then read at a check in the same
// procedure -- no call, no self-reference. Distinct from
// 01-global_default_zero.vimp (a global read before any write, at its
// zero-initialized default) and from 12-widening/precision/01-global_self_feedback
// .vimp (a write that reads the global's own prior value): this is the plain
// case that has neither, and it pins that having a global at all costs no
// precision.

global g;
fun main() {
  g = 1;
  __voblint_check(0 < g); // PROVED
}

// Glocal is spelled like a global-naming convention but is never declared
// global, so declared_global_vars excludes it: it is an ordinary local,
// routed flow-sensitively through every call like any other local, and its
// exact value survives untouched no matter how many times p is called.
// Declaration -- never spelling -- decides globality; see
// 02-counter_widened_by_call.vimp for the properly declared global counter
// in this same program, which the
// repeated call widens.
global counter;
fun p() {
  counter = counter + 1;
}
fun main() {
  Glocal = 1;
  p();
  p();
  __voblint_check(Glocal == 1); // PROVED
}

// x := 0; x := 1; check(x == 1) with x a declared global and no call in
// between. The current pipeline proves the check: within one procedure a
// declared global lives in the same reachability-lifted local unknown as
// every local (see 02-global_var.vimp), so the second write's exact value
// reaches the check with no flow-insensitive join against the first --
// there is no separate shared-slot summary here for the two writes to join
// through. Contrast with 07-sequential_local_proved.vimp, the same
// sequence with x an ordinary local: both give the identical exact result,
// which is the point -- declaring x global costs nothing as long as no call
// crosses it.
global x;
fun main() {
  x = 0;
  x = 1;
  __voblint_check(x == 1); // PROVED
}

// The contrasting baseline for 06-sequential_global_proved.vimp: the same
// x := 0; x := 1; check(x == 1) sequence, but x is an ordinary local.
// Tracked flow-sensitively per program point, so the second write's exact
// value reaches the check with no join against the first -- identical
// result to the global version, since no call ever crosses x in either.
fun main() {
  x = 0;
  x = 1;
  __voblint_check(x == 1); // PROVED
}

// Declaration, not spelling, decides storage class: p writes both the
// declared global counter and the undeclared Glocal. combine keeps the
// caller's locals and adopts the callee's globals, so main sees counter's
// write and not Glocal's. If Glocal were classified global, Glocal == 1
// would be REFUTED. One call site, so counter's seed has one origin and
// needs no widening (contrast known-imprecision/02-counter_widened_by_call.vimp).
//
// Ported from Example_Inc_Proc.thy (inc_program_counter_global,
// inc_program_glocal_not_global, prog_pcompletes_inc_pcall).
global counter;
fun p() {
  counter = counter + 1;
  Glocal = 7;
}
fun main() {
  Glocal = 1;
  p();
  __voblint_check(Glocal == 1); // PROVED
  __voblint_check(counter == 1); // PROVED
}

// Gx = 4; inc(); sqr(); with inc adding 1 to the declared global and sqr
// squaring it. The global is analyzed flow-sensitively through both calls
// (see 02-global_var.vimp), so (4 + 1) * (4 + 1) = 25 reaches the check
// exactly. The EXPECT-GRAPH block pins the compiled interprocedural CFG:
// inc at pp0-pp1, sqr at pp2-pp3, main from pp4, calls at pp5 and pp6.
//
// Ported from Example_Proc_Call.thy: main_prog_result (the concrete run,
// here as the analysis result) and main_cfg_full (the layout).


global Gx;
fun inc() {
  Gx = Gx + 1;
}
fun sqr() {
  Gx = Gx * Gx;
}
fun main() {
  Gx = 4;
  inc();
  sqr();
  __voblint_check(Gx == 25); // PROVED
}

// Several checks in one program with different expected verdicts: this pins
// that one report carries all three, not any single verdict.
//
// The third check is deliberately a soundness case inside a precision
// fixture. y is an unconstrained __voblint_nondet_int(), so both a satisfying
// and a violating execution exist and UNKNOWN is the only sound answer --
// it is not a precision regression, and "fixing" it to PROVED or REFUTED
// would be unsound. The standalone version is
// 01-random/soundness/01-unknown_after_random.vimp.
fun main() {
  x = 5;
  __voblint_check(0 < x); // PROVED
  x = 0 - 1;
  __voblint_check(0 < x); // REFUTED
  y = __voblint_nondet_int();
  __voblint_check(0 < y); // UNKNOWN
}

// A constant-false check in reachable code is REFUTED, not NOWARN: unlike
// 06-reachability's check(false) sentinels, this location is not dead
// code, so the check actually executes and its condition is decidably
// false every time.
fun main() {
  x = 5;
  __voblint_check(false); // REFUTED
}

// Two checks with the same condition and opposite verdicts, with main written
// before the procedure it calls. The compiler lays out procedures before main,
// so the result lists f's check first while the source has main's first. Each
// report row carries its check's own source position as its label, so each
// verdict lands on its line; pairing rows with checks by order of occurrence
// would swap the two.
//
// Concretely x is 1 at main's check and 2 at f's (x is local to each).
fun main() {
  x = 1;
  __voblint_check(x == 1); // PROVED
  f();
}
fun f() {
  x = 2;
  __voblint_check(x == 1); // REFUTED
}

// Ported from Example_Interval_Checks_Store_Only.thy (checks_ivl_ex_classify_2/3/4,
// checks_ivl_ex_report_eval). The guard narrows the unconstrained x to [1,9]
// on the then-branch, so the upper bound proves x < 11 and the lower bound
// refutes x < 0. x == 5 is genuinely undetermined on [1,9], so UNKNOWN is the
// only sound answer there.
fun main() {
  x = __voblint_nondet_int();
  if (0 < x && x < 10) {
    __voblint_check(x < 11); // PROVED
    __voblint_check(x < 0); // REFUTED
    __voblint_check(x == 5); // UNKNOWN
  } else {
    y = 0;
  }
}

// Mirrors Goblint's "__goblint_check(1); // reachable": a trivially-true
// condition isolates "does this location produce a report entry at all"
// (a CFG-compilation completeness property) from "is the analysis precise
// enough to prove this specific fact" -- 'true' is provable in every
// abstract state, live or dead, so its presence is the only thing being
// tested here. x is unconstrained (__voblint_nondet_int()), not a known exact value, so
// neither if-branch is infeasible -- both stay genuinely reachable, unlike
// an exact guard (see infeasible_guard_nowarn.vimp, where a known-exact x
// makes one branch provably dead).
fun main() {
  x = __voblint_nondet_int();
  __voblint_check(true); // reachable
  if (x < 10) {
    __voblint_check(true); // reachable
  } else {
    __voblint_check(true); // reachable
  }
}

// Code after 'return' is unreachable: mirrors Goblint's
// "__goblint_check(0); // NOWARN (unreachable)". The dead check's report
// row carries DEAD in place of a verdict: the analysis proves the point
// unreachable and says so, where Goblint only stays silent, and never
// prints the vacuous PROVED a bottom state would otherwise satisfy.
// main itself may not contain a return (wf_source_program's no_return
// conjunct), so the return lives in a helper procedure p instead, called
// destination-less.
fun p() {
  x = 5;
  __voblint_check(0 < x); // PROVED
  return x;
  __voblint_check(0 < x); // NOWARN
}
fun main() {
  p();
}

// A NOWARN case that is NOT return-based: x is narrowed to [5,5], so the
// "if (x < 0)" branch is infeasible. bfilter correctly detects this and
// narrows x to an empty (but non-canonical) interval there, e.g.
// Ivl (Fin 5) (Fin (-1)) -- not the canonical Ivl PlusInf MinInf bot. This
// case is why is_bottom_ivl compares bounds directly rather than testing
// "<= bot": a "<= bot" test would miss this branch's emptiness entirely
// (it only matches the one canonical representative), silently leaving a
// dead check visible with a vacuous PROVED verdict.
fun main() {
  x = 5;
  if (x < 0) {
    __voblint_check(x == 5); // NOWARN
  } else {
    __voblint_check(true); // PROVED
  }
}

// Literal Goblint idiom (https://goblint.readthedocs.io/en/latest/developer-guide/testing/):
// "__goblint_check(0); // NOWARN (unreachable)" -- a constant-false check as
// a dead-code sentinel, rather than a real condition that happens to be
// dead (see 02-unreachable_nowarn.vimp for that variant). VIMP has no
// integer truthiness, so the literal constant is the bexp "false" itself.
// main itself may not contain a return (wf_source_program's no_return
// conjunct), so the return lives in a helper procedure p instead, called
// destination-less.
fun p() {
  x = 5;
  __voblint_check(true); // PROVED
  return x;
  __voblint_check(false); // NOWARN (unreachable)
}
fun main() {
  p();
}

// Same literal check(false)/check(true) idiom as
// 04-unreachable_after_return_literal.vimp, but the dead code is an
// infeasible branch (exact guard) instead of code after return -- the
// other NOWARN mechanism 03-infeasible_guard_nowarn.vimp exercises with a
// real condition instead of the literal sentinel.
fun main() {
  x = 5;
  if (x < 0) {
    __voblint_check(false); // NOWARN (unreachable)
  } else {
    __voblint_check(true); // PROVED
  }
}

// Entry-state sibling of 05-unreachable_dead_branch_literal.vimp: the same
// infeasible branch, analyzed with --context entry-state instead of the
// context-insensitive default. The two paths reach the DEAD row by
// different routes and must agree.
//
// Context-insensitively, analyse_with_state carries one is-unreachable flag
// per check and the CLI prints those rows as DEAD. Context-sensitively there
// is no single flag to carry: one check node has one verdict per covered
// calling context, and a node can be dead in some and live in others. The
// verdict is therefore a contextual_verdict (Contextual_Check_Report.thy) --
// Bot when every covered context is unreachable there, a lifted verdict
// otherwise -- and the CLI prints exactly the Bot rows as DEAD.
//
// Without that distinction the row is not merely imprecise, it is wrong:
// an unreachable point's abstract state is bottom, bottom satisfies every
// condition vacuously, and the check reports PROVED for a comparison no
// execution ever performs.
//
// The graph block below is the same distinction at the rendering surface: the
// dead check node carries "[dead]" and no state lines at all, where reading
// the solved unknown directly would have drawn it as an undecided check over
// an x=⊥ store -- a live-looking node in the same grey a check the
// abstraction genuinely could not settle carries.

fun main() {
  x = 5;
  if (x < 2) {
    __voblint_check(x == 99); // NOWARN (unreachable)
  } else {
    __voblint_check(x == 5); // PROVED
  }
}

// The branch transfer's forward feasibility gate, not backward narrowing, is
// what makes this branch dead. Backward narrowing alone cannot: bfilter's Eq
// case inverts "(x < 0) == 1" to an empty target for its left operand, but
// afilter has no narrowing rule for a comparison node, so the empty target is
// dropped and the incoming state survives unchanged. The gate instead
// evaluates the whole condition forward -- interval_tobool of [0,0] answers
// Some False -- and contradicts the selected polarity, so the then-branch has
// no successor at all and its check is reported DEAD.
fun main() {
  x = 5;
  if ((x < 0) == 1) {
    __voblint_check(false); // NOWARN (unreachable)
  } else {
    __voblint_check(true); // PROVED
  }
}

// Adapted from Goblint tests/regression/00-sanity/05-inf_loop.c and
// 03-practical/09-nonterm2.c. The loop body is reachable, so its check(false)
// is REFUTED (Goblint: FAIL!). The loop's exit edge is the guard's negation,
// !(true), and the branch gate evaluates it to Some False in every state:
// nothing after the loop has a successor, so both trailing checks are
// reported DEAD (Goblint: NOWARN (unreachable), formerly NONTERM). The
// second trailing check reads x so the DEAD row is seen to hold for a
// check over a bound variable, not only for the literal sentinel.
fun main() {
  x = 0;
  while (true) {
    __voblint_check(false); // REFUTED
  }
  __voblint_check(false); // NOWARN (unreachable)
  __voblint_check(x == 0); // NOWARN (unreachable)
}

// Adapted from Goblint tests/regression/03-practical/22-nested-infinite-loops.c
// (issue #231), which only asks that the CFG survive; the checks here pin
// which points are live. The inner while (true) never exits, so the outer
// body's tail and everything after the outer loop are dead: their checks are
// reported DEAD. The check at the top of the outer body runs on every entry of the
// outer loop, and since the outer loop's back edge is itself dead, x is still
// exactly 0 there -- the head sees only its entry state.
fun main() {
  x = 0;
  while (true) {
    __voblint_check(x == 0); // PROVED
    while (true) {
      x = x + 1;
    }
    x = x - 1;
    __voblint_check(false); // NOWARN (unreachable)
  }
  x = x - 1;
  __voblint_check(false); // NOWARN (unreachable)
}

// Adapted from Goblint tests/regression/00-sanity/26-strict-loop-enter.c.
// The counted loop's head widens to [0,+inf] before narrowing brings it back
// to [0,50], so the branch 50 < x is live at the widened value and dead after
// narrowing. Goblint's note is that the node after Pos(x>50) ends up dead
// while the diverging inner loop keeps its widened x = [51,2147483647]; here
// the TD solver re-evaluates the branch's dependents on narrowing, so the
// inner loop head, its body and the check after it all end at bot and the
// check is reported DEAD (Goblint: NOWARN (unreachable)). The x == 50 check pins
// that the loop head was narrowed, not merely widened and joined.
//
// Solver-invariant: 15/16/17 in this directory are the same program under
// --globals join/per-origin/warrow-per-origin and agree on both verdicts,
// the NOWARN included.
global g;
fun main() {
  x = 0;
  while (x < 50) {
    g = 1;
    x = x + 1;
  }
  __voblint_check(x == 50); // PROVED
  if (50 < x) {
    i = 0;
    while (i <= 0) {
      g = 57;
      i = i - 1;
    }
    __voblint_check(true); // NOWARN (unreachable)
  }
}

// Adapted from Goblint tests/regression/02-base/58-empty-not-dead.c. The
// program declares no variable at all, so the abstract state at every point is
// the empty map. Goblint's concern is that a Hoare-set reduce drops the bot
// element of an empty local state and marks the code dead; the analogue here
// is the reachability probe over program_vars: with nothing to probe it must
// answer "live", not vacuously "bottom". Every check(true) is PROVED, in main
// and across a call into an equally empty procedure.
fun p() {
  __voblint_check(true); // PROVED
}
fun main() {
  __voblint_check(true); // PROVED
  p();
  __voblint_check(true); // PROVED
}

// Sign sibling of 11-empty_not_dead_interval.vimp (Goblint
// tests/regression/02-base/58-empty-not-dead.c): the reachability probe over
// an empty variable set is domain-generic, so a program with no variables
// stays live under Sign as well. int and parity give the same three PROVED
// rows.
fun p() {
  __voblint_check(true); // PROVED
}
fun main() {
  __voblint_check(true); // PROVED
  p();
  __voblint_check(true); // PROVED
}

// Adapted from Goblint tests/regression/33-constants/03-empty-not-dead-branch.c,
// where a branch with no locals produced an empty path-sensitive state after
// the join and raised Deadcode on the next assignment. main has no locals; g
// is the only variable, read nondeterministically so both arms are live. The
// join keeps g = [1,2], so 0 < g is PROVED, and the following write is still
// reached: g == 3 is PROVED, not absent.
global g;
fun main() {
  g = __voblint_nondet_int();
  if (g) {
    g = 1;
  } else {
    g = 2;
  }
  __voblint_check(0 < g); // PROVED
  g = 3;
  __voblint_check(g == 3); // PROVED
}

// Adapted from Goblint tests/regression/00-sanity/27-uncalled.c, where the
// uncalled function only earns a "will never be called" warning. Here foo's
// FunctionEntry has no call edge feeding it, so its seed is bot, every point
// inside foo is unreachable, and its check is reported DEAD. main's
// own check is still live.
fun foo() {
  __voblint_check(true); // NOWARN (unreachable)
}
fun main() {
  x = 0;
  __voblint_check(x == 0); // PROVED
}

