// Bounding witness for issue #77: a self-recursive procedure called at a
// depth (50) far exceeding the call-string bound (1). cs_route truncates
// every routed context to length <= 1 (cs_route_length,
// Call_String_Context.thy), so fact's own recursive call site produces at
// most 2 distinct call-string contexts (length 0 and length 1) no matter
// how deep the concrete recursion runs -- proved in general for any
// compiled program by compiled_call_strings_finite
// (Context_Space_Finite.thy), not just observed here. The CLI
// completes immediately rather than growing one context per recursion
// level, which is exactly the context-explosion #77 is about. The
// EXPECT-GRAPH block below now shows that directly: three clusters for a
// 50-deep recursion, the bound's own arithmetic rather than the program's
// call depth.
// The check itself stays UNKNOWN, not PROVED, and for a different reason than
// the context bound: at depth 1 the recursive call site's own context is
// truncated to a single entry, so every activation below the first shares one
// key. The callee-entry seed is again the join over those depths, and interval
// widening on the accumulating multiplication drives the result to an
// unbounded bound. Bounding context growth is what this fixture witnesses;
// recovering the value would need a key that separates depths, which is what
// --context entry-state does for the shallow case in
// 03-procedures/precision/06.

fun fact(n) {
  if (n < 2) {
    return 1;
  } else {
    tmp = fact(n - 1);
    return n * tmp;
  }
}
fun main() {
  r = fact(50);
  __voblint_check(0 < r); // UNKNOWN
}

// At call-string depth 1, g's routed context remembers only its own
// immediate call site (the call inside f's body), which is the same
// source location regardless of which f activation reaches it. The two
// activations of g -- one from f(3), one from f(10) -- therefore collapse
// onto the same routed context and widen together, so g's result, and
// everything downstream that reads it, loses precision: both x and y come
// back as [6,+inf) instead of their exact values 6 and 20. The K1/K2
// Isabelle witnesses pin the same separation on their solved states.

fun g(p) { return p + p; }
fun f(p) { t = g(p); return t; }
fun main() {
  x = f(3);
  y = f(10);
  __voblint_check(x == 6); // UNKNOWN
  __voblint_check(y == 20); // UNKNOWN
}

// Adapted from Goblint tests/regression/79-callstring/01-multiple_tests_h5sens_cs.c
// and 02-multiple_tests_h5ins_cs.c (ana.context.callString_length 5, i.e.
// --context call-string --context-depth 5). Goblint proves a(7), e(5),
// k(9) and o(5) (its widening delay tolerates about three collapsed
// levels) and reports the 02 checks UNKNOWN; voblint reports all of them
// UNKNOWN. Every concrete result is fixed, so this is imprecision, not
// underdetermination.
// The call string is exact only while the deepest activation chain fits in
// K call sites. Beyond that every deeper activation carries the same
// truncated key, so one callee-entry seed is the join of their arguments
// (--graph-snapshot: a's collapsed context enters with i=[0,2] for a(7)).
// What each family then loses, measured:
// - a/b/c and k/h: the joined seed contains 0 next to positive values.
//   Interval's guard refinement for (i != 0) cannot strip the endpoint 0
//   from [0,2], so the following (i <= 0) arm keeps i=[0,0] and its
//   fall-through `return 1` becomes live; the collapsed exit joins to
//   [1,11]. --analysis int proves a(7), a(8), c(11) and b(21) at this same
//   depth: its Sign component refines (i != 0) on NonNegative to Positive
//   and the product refinement lifts the interval to [1,2], which kills the
//   arm. k(9) stays UNKNOWN under int too, because the joined seed admits
//   i=0 through the recursive arm (k(1) -> k(0)) that the concrete run
//   never takes (k stops at 2), and the fall-through `return 1` is live.
// - e/f: the collapsed activations return different concrete values
//   (e(1) = 3, e(3) = 4), so their joined exit is a genuine range; no
//   domain refinement separates depths that share a key.
// - o with the global m: the collapsed context is entered from three call
//   chains, warrowing widens its seed to i=[0,+inf], the body writes m := i
//   from it, and m reads back as [0,+inf] after each call.
// --context entry-state proves every check in this file.
global m;
fun a(i) {
  if (i == 0) { return 11; }
  if (0 < i) { r = a(i - 1); return r; }
  return 1;
}
fun b(i) {
  if (i == 0) { return 12; }
  if (0 < i) { r = a(i - 1); return r; }
  return 2;
}
fun c(i) {
  if (i == 0) { return 13; }
  if (0 < i) { r = b(i - 1); return r; }
  return 3;
}
fun f(i) {
  if (0 < i) { r = e(i - 1); return r; }
  return 2;
}
fun e(i) {
  r = f(i - 1);
  return r + 1;
}
fun h(i) {
  if (i == 0) { return 1; }
  if (0 < i) { r = h(i - 1); return r; }
  return 0;
}
fun k(i) {
  if (i == 2) { r = h(i - 1); return r + 1; }
  if (0 < i) { r = k(i - 1); return r; }
  return 1;
}
fun o(i) {
  if (0 < i) { i = i - 1; m = i; o(i); }
  return 0;
}
fun main() {
  x0 = a(7); __voblint_check(x0 == 11);  // UNKNOWN
  x1 = a(8); __voblint_check(x1 == 11);  // UNKNOWN
  x2 = c(11); __voblint_check(x2 == 11); // UNKNOWN
  x3 = b(21); __voblint_check(x3 == 11); // UNKNOWN
  y0 = e(5); __voblint_check(y0 == 5);   // UNKNOWN
  y1 = e(7); __voblint_check(y1 == 6);   // UNKNOWN
  z0 = k(9); __voblint_check(z0 == 2);   // UNKNOWN
  z1 = k(10); __voblint_check(z1 == 2);  // UNKNOWN
  m = 20; o(5); __voblint_check(m == 0); // UNKNOWN
  m = 20; o(6); __voblint_check(m == 0);  // UNKNOWN
}

// Same program as precision/12-depth5_nondet_branch_in_recursion.vimp
// (Goblint 80-context_gas/23-per-fun.c) at depth 2. The concrete result
// f(3, 3) == 0 is fixed. main -> f(3,3) -> f(2,2) keep distinct keys, but
// f(1,1), f(0,0) and every deeper level share the truncated key [f, f],
// so that one context re-enters itself with (x - 1, y - 1) and warrowing
// extrapolates its callee-entry seed to x=[-inf,1], y=[-inf,1]
// (--graph-snapshot). The x == 0 arm refines x alone -- the domain is
// non-relational -- and returns y=[-inf,1], which propagates back up the
// chain to a. The nr check stays proved because nr(5, 5) and nr(6, 6) are
// different call sites and get different keys at any depth.
fun nr(x, y) {
  __voblint_check(x == y); // PROVED
}
fun f(x, y) {
  if (x == 0) { return y; }
  top = __voblint_nondet_int();
  if (0 < top) { nr(5, 5); } else { nr(6, 6); }
  r = f(x - 1, y - 1);
  return r;
}
fun main() {
  a = f(3, 3);
  __voblint_check(a == 0); // UNKNOWN
}

// The browser playground's example, at its default configuration. At depth 1,
// scale's call string remembers only its call site inside wrap, so wrap(1)
// and wrap(4) share one scale context and widen together: v enters as
// [1,+inf] and the returned r, and so a and b, lose both bounds. a == 2 is
// concretely true but UNKNOWN, and 10 / (a - 2) -- concretely 10 / 0 -- is
// only a possible division by zero. record keeps one context per call site
// in main, so hits stays exact and hits == 8 is still proved.
global hits;

fun record(amount) {
  hits = hits + amount;
}

fun scale(v) {
  return v * 2;
}

fun wrap(w) {
  r = scale(w);
  return r;
}

fun main() {
  i = 0;
  while (i < 5) {
    i = i + 1;
  }
  __voblint_check(i == 5); // PROVED
  __voblint_check(i < 5); // REFUTED

  record(i);
  record(3);
  __voblint_check(hits == 8); // PROVED

  if (hits > 10) {
    record(100);
  }

  a = wrap(1);
  b = wrap(4);
  __voblint_check(a == 2); // UNKNOWN
  share = 10 / (a - 2); // ARITH: WARN division-by-zero
}

