// Adapted from Goblint tests/regression/79-callstring/01-multiple_tests_h5sens_cs.c
// and 03-multiple_tests_h2sens_cs.c (ana.context.callString_length 5, i.e.
// --context call-string --context-depth 5). The checks that Goblint proves
// at length 5 and voblint proves too: every activation chain here fits in
// five call sites (main -> a(4) -> ... -> a(0) is five sites; c(4) -> b(3)
// -> a(2) -> a(1) -> a(0) likewise), so each activation keeps its own
// call-string key, no two depths share a callee-entry seed, and every
// argument stays a singleton interval. The a(7), a(8), e(5), k(9) and o(5)
// checks of the same Goblint file need deeper chains and stay UNKNOWN;
// they live in known-imprecision/03-depth5_collapsed_deep_chain.vimp.
// k(6) is Goblint's 03 Test 3 at length 2, where voblint answers UNKNOWN
// (see precision/08); at depth 5 it fits and is proved.
// --context entry-state proves all of these as well.
fun a(i) {
  if (i == 0) { return 11; }
  if (0 < i) { r = a(i - 1); return r; }
  return 1;
}
fun b(i) {
  if (i == 0) { return 12; }
  if (0 < i) { r = a(i - 1); return r; }
  return 2;
}
fun c(i) {
  if (i == 0) { return 13; }
  if (0 < i) { r = b(i - 1); return r; }
  return 3;
}
fun f(i) {
  if (0 < i) { r = e(i - 1); return r; }
  return 2;
}
fun e(i) {
  r = f(i - 1);
  return r + 1;
}
fun h(i) {
  if (i == 0) { return 1; }
  if (0 < i) { r = h(i - 1); return r; }
  return 0;
}
fun k(i) {
  if (i == 2) { r = h(i - 1); return r + 1; }
  if (0 < i) { r = k(i - 1); return r; }
  return 1;
}
fun main() {
  x0 = a(0); __voblint_check(x0 == 11); // PROVED
  x1 = a(1); __voblint_check(x1 == 11); // PROVED
  x2 = a(4); __voblint_check(x2 == 11); // PROVED
  x3 = b(4); __voblint_check(x3 == 11); // PROVED
  x4 = c(4); __voblint_check(x4 == 11); // PROVED
  x5 = b(0); __voblint_check(x5 == 12); // PROVED
  x6 = c(0); __voblint_check(x6 == 13); // PROVED
  y0 = f(0); __voblint_check(y0 == 2);  // PROVED
  y1 = e(0); __voblint_check(y1 == 3);  // PROVED
  z0 = k(6); __voblint_check(z0 == 2);   // PROVED
}

// Adapted from Goblint tests/regression/79-callstring/03-multiple_tests_h2sens_cs.c
// (ana.context.callString_length 2, i.e. --context call-string
// --context-depth 2). Chains of at most two call sites keep exact keys, so
// the base cases of the a/b/c chain and the e/f pair are proved. The
// seven-procedure cyclic call graph m -> q -> o -> r -> q -> s -> p -> l ->
// q -> p -> l runs twelve activations deep, far past depth 2, and still
// proves m(4) == 4: every path through it ends in l's `return 4`, so
// collapsing keys joins equal values. --context none proves m(4) too.
// Goblint's k(6) == 2 check from the same file is UNKNOWN here at depth 2
// (the collapsed k seed admits i=0 and its fall-through `return 1`; see
// known-imprecision/03) and proved at depth 5 in precision/07.
fun a(i) {
  if (i == 0) { return 11; }
  if (0 < i) { r = a(i - 1); return r; }
  return 1;
}
fun b(i) {
  if (i == 0) { return 12; }
  if (0 < i) { r = a(i - 1); return r; }
  return 2;
}
fun c(i) {
  if (i == 0) { return 13; }
  if (0 < i) { r = b(i - 1); return r; }
  return 3;
}
fun f(i) {
  if (0 < i) { r = e(i - 1); return r; }
  return 2;
}
fun e(i) {
  r = f(i - 1);
  return r + 1;
}
fun l(i) {
  if (i == 0) { r = q(2); return r; } else { return 4; }
}
fun p(i) { r = l(i - 1); return r; }
fun s(i) { r = p(i - 1); return r; }
fun r(i) { t = q(i - 1); return t; }
fun o(i) {
  if (i <= 0) { t = r(4); return t; } else { t = o(i - 1); return t; }
}
fun q(i) {
  if (i == 4) { t = o(3); return t; }
  if (i == 3) { t = s(2); return t; }
  t = p(20);
  return t;
}
fun m(i) { t = q(i); return t; }
fun main() {
  x0 = a(1); __voblint_check(x0 == 11); // PROVED
  x1 = a(0); __voblint_check(x1 == 11); // PROVED
  x2 = b(0); __voblint_check(x2 == 12); // PROVED
  x3 = c(0); __voblint_check(x3 == 13); // PROVED
  y0 = f(0); __voblint_check(y0 == 2);  // PROVED
  y1 = e(0); __voblint_check(y1 == 3);  // PROVED
  z = m(4); __voblint_check(z == 4);     // PROVED
}

// Adapted from Goblint tests/regression/79-callstring/06-big_loop_cs.c
// (ana.context.callString_length 10; --context-depth 2 already suffices
// here). Mutual recursion f <-> g called from a 200-iteration loop. Each
// chain is three sites deep (main -> f(2) -> g(1) -> f(0)), so depth 2
// keeps f(2) and g(2) apart from the inner f(0)/g(0) activations and both
// results are exact. The loop counter is widened to [0,200] as usual; the
// callee keys carry no loop state, so the 200 iterations add no contexts.
// --context none answers UNKNOWN for both (res1=[1,12]): f and g each have
// one activation shared by every call site, the same mechanism as
// 03-procedures/known-imprecision/01-two_call_sites_same_procedure.vimp.
fun g(i) {
  if (i == 0) { return 1; }
  if (0 < i) { r = f(i - 1); return r; }
  return 11;
}
fun f(i) {
  if (i == 0) { return 2; }
  if (0 < i) { r = g(i - 1); return r; }
  return 12;
}
fun main() {
  i = 200;
  while (0 < i) {
    res1 = f(2);
    res2 = g(2);
    __voblint_check(res1 == 2); // PROVED
    __voblint_check(res2 == 1); // PROVED
    i = i - 1;
  }
}

// Adapted from Goblint tests/regression/79-callstring/05-ackermann_cs.c
// (ana.context.callString_length 10). Termination witness, not a value
// check: ack(4, 1) is astronomically deep in the concrete, and the
// call-string bound is what keeps the context space finite
// (compiled_call_strings_finite). Measured cost by depth: K=3 about 1 s,
// K=4 about 5 s, K>=5 does not finish within a minute. The fixture pins
// K=3 with an explicit --timeout so a solver-level regression surfaces as
// a structured timeout rather than a hung suite. `reachable` only asserts
// the check after the call is reported.
fun ack(n, m) {
  if (n == 0) { return m + 1; } else {
    if (m == 0) { r = ack(n - 1, 1); return r; } else {
      t = ack(n, m - 1);
      r = ack(n - 1, t);
      return r;
    }
  }
}
fun main() {
  x = ack(4, 1);
  __voblint_check(true); // reachable
}

// Adapted from Goblint tests/regression/81-loopfree_callstring/10-nested_loops.c
// (loopfree_callstring, which has no voblint equivalent; a plain
// call-string of depth 5 is used instead, and Goblint's own annotation is
// UNKNOWN). The chain main -> f(4) -> f(3) -> f(2) -> f(1) -> f(0) -> g(2)
// -> h(2) is seven sites deep, but the value 3 is produced by h and only
// passed back, so all that matters is that f(0)'s key differs from the
// keys of the activations still recursing. At depth 5 it does: the
// collapsed f activations f(1)/f(0) are exactly the ones whose g call is
// live, and g/h return a constant. At depth 2 the answer is UNKNOWN
// (a=[0,3]): the collapsed f seed admits every i in [0,2], and its
// fall-through `return 0` arm is live through Interval's (i != 0) guard
// keeping the endpoint 0 (see known-imprecision/03 for that mechanism).
fun h(i) { return 3; }
fun g(i) { r = h(i); return r; }
fun f(i) {
  if (i == 0) { r = g(2); return r; }
  if (0 < i) { r = f(i - 1); return r; }
  return 0;
}
fun main() {
  a = f(4); __voblint_check(a == 3); // PROVED
}

// Adapted from Goblint tests/regression/80-context_gas/23-per-fun.c
// (ana.context.gas_value 3 with gas_scope function; context gas has no
// voblint equivalent, and Goblint's own annotation for a == 0 is UNKNOWN).
// Two-formal recursion f(x, y) with a nondeterministic branch that calls a
// non-recursive nr(5, 5) or nr(6, 6) before recursing. Both nr call sites
// are distinct, so even at depth 1 each has its own key and x == y is
// proved inside nr; the branch merges the caller state afterwards without
// touching x or y. main -> f(3,3) -> ... -> f(0,0) is five sites, so at
// depth 5 every f activation keeps its own key and a == 0 is exact. At
// depth 2 the deeper activations f(1,1) and f(0,0) share a key
// (known-imprecision/04). --context none proves neither check.
fun nr(x, y) {
  __voblint_check(x == y); // PROVED
}
fun f(x, y) {
  if (x == 0) { return y; }
  top = __voblint_nondet_int();
  if (0 < top) { nr(5, 5); } else { nr(6, 6); }
  r = f(x - 1, y - 1);
  return r;
}
fun main() {
  a = f(3, 3);
  __voblint_check(a == 0); // PROVED
}

// Adapted from Goblint tests/regression/32-widen-context/01-on.c
// (ana.context.widen enabled). f(x) recurses on x + 1 whenever x is
// nonzero, so f(1) never returns over VIMP's mathematical integers: the
// check after the call is dead and is suppressed (NOWARN). Goblint
// annotates the same check as proved because its C int wraps to 0 after
// overflow (or is widened to top, which its `!a` check tolerates); that is
// a semantic difference between C machine integers and VIMP's unbounded
// ints, not a precision difference. The bounded call string keeps the
// context space finite; under --context entry-state the same program
// creates a fresh context per x value and diverges, which
// 21-context-sensitivity/01-unbounded_context_chain_diverges.vimp pins
// through --timeout.
fun f(x) {
  if (x != 0) { r = f(x + 1); return r; } else { return x; }
}
fun main() {
  a = f(1);
  __voblint_check(a == 0); // NOWARN
}

// Call-string GraphViz coverage at Congruence, the sibling of
// 05-callstring_graph_sign.vimp and 06-callstring_graph_int.vimp.
//
